import { forbidden } from 'next/navigation';

import { verifyAdmin } from '../lib/auth';

export default async function AdminPage() {
  const { isAdmin, session } = await verifyAdmin();

  if (!isAdmin) {
    forbidden();
  }

  return (
    <main
      style={{
        minHeight: '100vh',
        padding: '48px 24px',
        background: 'linear-gradient(140deg, #f8f3ea 0%, #e6f2f5 100%)',
        color: '#16202a',
        fontFamily: '"Palatino Linotype", "Book Antiqua", Palatino, serif'
      }}
    >
      <section
        style={{
          maxWidth: '720px',
          margin: '0 auto',
          padding: '32px',
          borderRadius: '20px',
          background: '#fffaf3',
          boxShadow: '0 20px 60px rgba(22, 32, 42, 0.12)',
          border: '1px solid rgba(22, 32, 42, 0.08)'
        }}
      >
        <p style={{ margin: 0, fontSize: '14px', letterSpacing: '0.12em' }}>
          ADMIN AREA
        </p>
        <h1 style={{ margin: '12px 0 8px', fontSize: '40px' }}>
          Welcome back, {session?.name ?? 'Admin'}
        </h1>
        <p style={{ margin: 0, fontSize: '18px', lineHeight: 1.6 }}>
          This space is reserved for administrative tasks and sensitive data.
          Only verified admins can access it.
        </p>
      </section>
    </main>
  );
}
